<?php
declare(strict_types=1); namespace Theobroma\OneC\Ozon;
final class OzonTableParser {/** @return list<OzonRow> */public function parse(string $contents):array{if(strlen($contents)>5*1024*1024)throw new \InvalidArgumentException('File exceeds 5 MB');$contents=preg_replace('/^\xEF\xBB\xBF/','',$contents)??$contents;$lines=preg_split('/\R/u',trim($contents))?:[];if(!$lines)return[];$delimiter=substr_count($lines[0],"\t")>=substr_count($lines[0],',')?"\t":',';$headers=str_getcsv(array_shift($lines),$delimiter);$map=array_flip($headers);foreach(['Артикул','Ozon Product ID','SKU','Штрихкод (Серийный номер / EAN)','Название товара']as$h)if(!isset($map[$h]))throw new \InvalidArgumentException("Missing column: $h");if(count($lines)>5000)throw new \InvalidArgumentException('File exceeds 5000 rows');$out=[];foreach($lines as$line){if(trim($line)==='')continue;$v=str_getcsv($line,$delimiter);$get=fn($h)=>trim((string)($v[$map[$h]]??''));$product=$get('Ozon Product ID');$sku=$get('SKU');$ean=$get('Штрихкод (Серийный номер / EAN)');$valid=$product!==''&&ctype_digit($product)&&($sku===''||ctype_digit($sku))&&($ean===''||preg_match('/^(?:\d{8,14}|OZN\d+)$/',$ean)===1);$out[]=new OzonRow($get('Артикул'),$product,$sku,$ean,$get('Название товара'),$valid);}return$out;}}
